public async Task HoldLockAsync(string key, Func<FencingToken, CancellationToken, Task> criticalSection)
{
    // Bounded wait: never block forever, never silently proceed without a lock
    var lease = await lockClient.AcquireAsync(key, lease: TimeSpan.FromSeconds(30),
        wait: TimeSpan.FromSeconds(5), cancellationToken: ct);

    if (lease is null)
        throw new LockUnavailableException(key);

    using var renewal = new CancellationTokenSource();
    var renewTask = Task.Run(async () =>
    {
        while (!renewal.IsCancellationRequested)
        {
            await Task.Delay(TimeSpan.FromSeconds(10), renewal.Token);
            if (!await lockClient.RenewAsync(lease, cancellationToken: renewal.Token))
            {
                // We lost the lock. Signal the critical section to abort.
                await lease.SignalLostAsync();
                return;
            }
        }
    });

    try
    {
        // Every write inside the section carries the token
        await criticalSection(lease.FencingToken, lease.LostToken);
    }
    finally
    {
        renewal.Cancel();
        await renewTask;
        await lockClient.ReleaseAsync(lease);
    }
}
